CREATE TYPE "ScanStatus" AS ENUM ('queued','collecting','mapping','analyzing','correlating','judging','verifying','challenging','cancelling','cancelled','completed','failed');
CREATE TYPE "Completeness" AS ENUM ('complete','partial');
CREATE TYPE "Verdict" AS ENUM ('run','review','avoid');
CREATE TYPE "Confidence" AS ENUM ('low','medium','high');
CREATE TABLE "RepositoryScan" ("id" TEXT PRIMARY KEY,"publicId" TEXT NOT NULL UNIQUE,"sessionHash" TEXT NOT NULL,"normalizedUrl" TEXT NOT NULL,"owner" TEXT NOT NULL,"repository" TEXT NOT NULL,"requestedRef" TEXT,"defaultBranch" TEXT,"commitSha" TEXT,"status" "ScanStatus" NOT NULL DEFAULT 'queued',"progress" INTEGER NOT NULL DEFAULT 0,"progressMessage" TEXT NOT NULL DEFAULT 'Queued',"completeness" "Completeness" NOT NULL DEFAULT 'partial',"promptVersion" TEXT NOT NULL DEFAULT '2026-09-28.v1',"analysisModel" TEXT NOT NULL,"verifierModel" TEXT NOT NULL,"usageJson" JSONB,"budgetJson" JSONB,"failureCode" TEXT,"failureMessage" TEXT,"cancelRequestedAt" TIMESTAMP(3),"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RepositorySnapshot" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL UNIQUE REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"repositoryJson" JSONB NOT NULL,"ownerJson" JSONB NOT NULL,"inventoryCount" INTEGER NOT NULL,"inventoryBytes" INTEGER NOT NULL,"selectedBytes" INTEGER NOT NULL,"skippedJson" JSONB NOT NULL,"coverageJson" JSONB NOT NULL,"commandsJson" JSONB NOT NULL,"dependenciesJson" JSONB NOT NULL,"mapJson" JSONB NOT NULL,"intentJson" JSONB NOT NULL,"headShaLastSeen" TEXT,"headCheckedAt" TIMESTAMP(3),"rawDeleteAfter" TIMESTAMP(3) NOT NULL);
CREATE TABLE "FileRecord" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"path" TEXT NOT NULL,"contentHash" TEXT,"typeGuess" TEXT NOT NULL,"size" INTEGER NOT NULL,"selected" BOOLEAN NOT NULL DEFAULT false,"skipReason" TEXT,"priorityReasons" JSONB NOT NULL,"content" TEXT,"rawDeleteAfter" TIMESTAMP(3),UNIQUE("scanId","path"));
CREATE TABLE "Observation" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"filePath" TEXT NOT NULL,"lineStart" INTEGER NOT NULL,"lineEnd" INTEGER NOT NULL,"excerpt" TEXT NOT NULL,"category" TEXT NOT NULL,"capability" TEXT NOT NULL,"basis" TEXT NOT NULL,"severity" TEXT NOT NULL,"confidence" TEXT NOT NULL,"detailsJson" JSONB NOT NULL,"evidenceValid" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "EvidenceChain" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"stepsJson" JSONB NOT NULL,"edgesJson" JSONB NOT NULL,"impact" TEXT NOT NULL,"severity" TEXT NOT NULL,"confidence" TEXT NOT NULL,"evidenceValid" BOOLEAN NOT NULL DEFAULT false,"verificationResult" TEXT);
CREATE TABLE "Finding" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"summary" TEXT NOT NULL,"category" TEXT NOT NULL,"severity" TEXT NOT NULL,"confidence" TEXT NOT NULL,"behavior" TEXT NOT NULL,"evidenceIds" JSONB NOT NULL,"whyItMatters" TEXT NOT NULL,"benignAlternative" TEXT,"advice" TEXT NOT NULL);
CREATE TABLE "ScanDecision" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL UNIQUE REFERENCES "RepositoryScan"("id") ON DELETE CASCADE,"recommendation" "Verdict" NOT NULL,"confidence" "Confidence" NOT NULL,"decidedBy" TEXT NOT NULL,"judgeProposal" "Verdict" NOT NULL,"judgeConfidence" "Confidence" NOT NULL,"judgePolicyAgreement" BOOLEAN NOT NULL,"disagreementReason" TEXT,"primaryReason" TEXT NOT NULL,"decisiveFindingIds" JSONB NOT NULL,"commandsJson" JSONB NOT NULL,"precautionsJson" JSONB NOT NULL,"nextStepsJson" JSONB NOT NULL,"disclaimer" TEXT NOT NULL,"gatesJson" JSONB NOT NULL);
CREATE TABLE "ExternalIntelligenceResult" ("id" TEXT PRIMARY KEY,"provider" TEXT NOT NULL,"queryType" TEXT NOT NULL,"subject" TEXT NOT NULL,"retrievedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"advisoryId" TEXT,"provenanceUrl" TEXT,"classification" TEXT NOT NULL,"normalizedJson" JSONB NOT NULL,"responseHash" TEXT);
CREATE INDEX "RepositoryScan_normalizedUrl_commitSha_promptVersion_idx" ON "RepositoryScan"("normalizedUrl","commitSha","promptVersion");
CREATE INDEX "RepositoryScan_status_createdAt_idx" ON "RepositoryScan"("status","createdAt");
CREATE INDEX "ExternalIntelligenceResult_provider_queryType_subject_expiresAt_idx" ON "ExternalIntelligenceResult"("provider","queryType","subject","expiresAt");
